import { relations, sql } from "drizzle-orm";
import {
  check,
  date,
  integer,
  jsonb,
  time,
  pgEnum,
  pgTable,
  serial,
  text,
  timestamp,
  uniqueIndex,
  index,
  varchar,
  boolean,
} from "drizzle-orm/pg-core";

export const serviceSetStatus = pgEnum("service_set_status", ["working", "final"]);
export const serviceLanguage = pgEnum("service_language", ["czech", "polish", "mixed"]);
export const songLanguage = pgEnum("song_language", ["czech", "polish"]);

export const referenceCatalogSongs = pgTable("reference_catalog_songs", {
  id: text("id").primaryKey(),
  language: songLanguage("language").notNull(),
  canonicalNumber: integer("canonical_number").notNull(),
  sourceId: text("source_id").notNull(),
  title: text("title").notNull(),
  sourceUrl: text("source_url"),
}, (table) => ({
  languageCanonicalNumber: uniqueIndex("reference_catalog_songs_language_canonical_number_idx").on(table.language, table.canonicalNumber),
  languageSourceId: uniqueIndex("reference_catalog_songs_language_source_id_idx").on(table.language, table.sourceId),
  positiveCanonicalNumber: check("reference_catalog_songs_canonical_number_positive", sql`${table.canonicalNumber} > 0`),
  nonEmptyId: check("reference_catalog_songs_id_non_empty", sql`btrim(${table.id}) <> ''`),
  nonEmptySourceId: check("reference_catalog_songs_source_id_non_empty", sql`btrim(${table.sourceId}) <> ''`),
  nonEmptyTitle: check("reference_catalog_songs_title_non_empty", sql`btrim(${table.title}) <> ''`),
}));

export const referenceAntiphons = pgTable("reference_antiphons", {
  id: text("id").primaryKey(),
  language: songLanguage("language").notNull(),
  canonicalNumber: integer("canonical_number").notNull(),
  title: text("title").notNull(),
  sourceUrl: text("source_url"),
}, (table) => ({
  languageCanonicalNumber: uniqueIndex("reference_antiphons_language_canonical_number_idx").on(table.language, table.canonicalNumber),
  positiveNumber: check("reference_antiphons_number_positive", sql`${table.canonicalNumber} > 0`),
  idMatchesNumber: check("reference_antiphons_id_matches_number", sql`${table.id} = ${table.language}::text || ':' || ${table.canonicalNumber}::text`),
  nonEmptyId: check("reference_antiphons_id_non_empty", sql`btrim(${table.id}) <> ''`),
  nonEmptyTitle: check("reference_antiphons_title_non_empty", sql`btrim(${table.title}) <> ''`),
  validSourceUrl: check("reference_antiphons_source_url_valid", sql`(
    ${table.language} = 'czech' and ${table.sourceUrl} is not null and ${table.sourceUrl} ~ '^https://www\\.evangelickykancional\\.cz(?:/|$)'
  ) or (
    ${table.language} = 'polish' and (${table.sourceUrl} is null or ${table.sourceUrl} ~ '^https://')
  )`),
}));

export const catalogPersons = pgTable("catalog_persons", {
  id: text("id").primaryKey(),
  displayName: text("display_name").notNull(),
  active: boolean("active").notNull().default(true),
  priest: boolean("priest").notNull().default(false),
  organist: boolean("organist").notNull().default(false),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const catalogSongs = pgTable("catalog_songs", {
  songId: text("song_id").primaryKey(),
  language: songLanguage("language").notNull(),
  number: text("number").notNull(),
  title: text("title").notNull(),
  active: boolean("active").notNull().default(true),
  sheetMusicUrl: text("sheet_music_url"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  languageNumber: uniqueIndex("catalog_songs_language_number_idx").on(table.language, table.number),
}));

export const serviceContexts = pgTable(
  "service_contexts",
  {
    id: serial("id").primaryKey(),
    name: varchar("name", { length: 255 }),
    serviceDate: date("service_date").notNull().default(sql`CURRENT_DATE`),
    serviceTime: time("service_time"),
    serviceLanguage: serviceLanguage("service_language").notNull().default("czech"),
    priestId: text("priest_id"),
    priestDisplayName: text("priest_display_name").notNull().default(""),
    organistId: text("organist_id"),
    organistDisplayName: text("organist_display_name").notNull().default(""),
    note: text("note"),
    referenceAntiphonId: text("reference_antiphon_id"),
    referenceAntiphonDisplayNumber: text("reference_antiphon_display_number"),
    referenceAntiphonTitle: text("reference_antiphon_title"),
    referenceAntiphonSourceUrl: text("reference_antiphon_source_url"),
    referenceTopicId: text("reference_topic_id"),
    referenceTopicTitle: text("reference_topic_title"),
    antiphonKey: text("antiphon_key"),
    liturgicalSeasonKey: text("liturgical_season_key"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => ({
    serviceDateTime: uniqueIndex("service_contexts_service_date_time_idx").on(table.serviceDate, table.serviceTime),
    referenceAntiphonSnapshotComplete: check(
      "service_contexts_reference_antiphon_snapshot_complete",
      sql`(
        ${table.referenceAntiphonId} is null and
        ${table.referenceAntiphonDisplayNumber} is null and
        ${table.referenceAntiphonTitle} is null and
        ${table.referenceAntiphonSourceUrl} is null
      ) or (
        ${table.referenceAntiphonId} is not null and
        ${table.referenceAntiphonDisplayNumber} is not null and
        ${table.referenceAntiphonTitle} is not null
      )`,
    ),
    referenceAntiphonIdentity: check(
      "service_contexts_reference_antiphon_identity",
      sql`${table.referenceAntiphonId} is null or ${table.referenceAntiphonId} ~ '^(czech|polish):[1-9][0-9]*$'`,
    ),
    referenceAntiphonSnapshotNonEmpty: check(
      "service_contexts_reference_antiphon_snapshot_non_empty",
      sql`${table.referenceAntiphonId} is null or (
        btrim(${table.referenceAntiphonDisplayNumber}) <> '' and
        btrim(${table.referenceAntiphonTitle}) <> ''
      )`,
    ),
    referenceAntiphonSourceUrlValid: check(
      "service_contexts_reference_antiphon_source_url_valid",
      sql`${table.referenceAntiphonSourceUrl} is null or ${table.referenceAntiphonSourceUrl} ~ '^https://'`,
    ),
    referenceTopicSnapshotComplete: check(
      "service_contexts_reference_topic_snapshot_complete",
      sql`(${table.referenceTopicId} is null and ${table.referenceTopicTitle} is null) or (${table.referenceTopicId} is not null and ${table.referenceTopicTitle} is not null)`,
    ),
    referenceTopicIdentity: check(
      "service_contexts_reference_topic_identity",
      sql`${table.referenceTopicId} is null or ${table.referenceTopicId} ~ '^(czech|polish):.+$'`,
    ),
    referenceTopicTitleNonEmpty: check(
      "service_contexts_reference_topic_title_non_empty",
      sql`${table.referenceTopicId} is null or btrim(${table.referenceTopicTitle}) <> ''`,
    ),
  }),
);

export const serviceSets = pgTable("service_sets", {
  id: serial("id").primaryKey(),
  serviceContextId: integer("service_context_id")
    .notNull()
    .references(() => serviceContexts.id, { onDelete: "cascade" }),
  status: serviceSetStatus("status").notNull().default("working"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const serviceSetRows = pgTable(
  "service_set_rows",
  {
    id: serial("id").primaryKey(),
    serviceSetId: integer("service_set_id")
      .notNull()
      .references(() => serviceSets.id, { onDelete: "cascade" }),
    position: integer("position").notNull(),
    songId: text("song_id"),
    songLanguage: songLanguage("song_language"),
    songNumber: text("song_number"),
    songTitle: text("song_title"),
    note: text("note"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => ({
    serviceSetPosition: uniqueIndex("service_set_rows_service_set_id_position_idx").on(
      table.serviceSetId,
      table.position,
    ),
    positivePosition: check("service_set_rows_position_positive", sql`${table.position} > 0`),
    completeSongReference: check(
      "service_set_rows_complete_song_reference",
      sql`(${table.songLanguage} is null and ${table.songNumber} is null) or (${table.songLanguage} is not null and ${table.songNumber} is not null)`,
    ),
  }),
);

export const completedServices = pgTable("completed_services", {
  id: serial("id").primaryKey(),
  serviceContextId: integer("service_context_id")
    .notNull()
    .references(() => serviceContexts.id, { onDelete: "cascade" }),
  serviceSetId: integer("service_set_id").references(() => serviceSets.id, { onDelete: "set null" }),
  completedAt: timestamp("completed_at", { withTimezone: true }).notNull().defaultNow(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const completedServiceRows = pgTable(
  "completed_service_rows",
  {
    id: serial("id").primaryKey(),
    completedServiceId: integer("completed_service_id")
      .notNull()
      .references(() => completedServices.id, { onDelete: "cascade" }),
    position: integer("position").notNull(),
    songId: text("song_id"),
    songLanguage: songLanguage("song_language"),
    songNumber: text("song_number"),
    songTitle: text("song_title"),
    note: text("note"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => ({
    completedServicePosition: uniqueIndex("completed_service_rows_completed_service_id_position_idx").on(
      table.completedServiceId,
      table.position,
    ),
    positivePosition: check("completed_service_rows_position_positive", sql`${table.position} > 0`),
    completeSongReference: check(
      "completed_service_rows_complete_song_reference",
      sql`(${table.songLanguage} is null and ${table.songNumber} is null) or (${table.songLanguage} is not null and ${table.songNumber} is not null)`,
    ),
  }),
);


export const preferenceProfileCategory = pgEnum("preference_profile_category", ["priest", "organist", "congregation_member"]);
export const userRole = pgEnum("user_role", ["priest", "organist", "admin", "congregation_member"]);

export const appUsers = pgTable("app_users", {
  id: text("id").primaryKey(),
  displayName: text("display_name").notNull(),
  personId: text("person_id").references(() => catalogPersons.id, { onDelete: "set null" }),
  active: boolean("active").notNull().default(true),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const appUserRoles = pgTable("app_user_roles", {
  userId: text("user_id").notNull().references(() => appUsers.id, { onDelete: "cascade" }),
  role: userRole("role").notNull(),
}, (table) => ({ userRoleUnique: uniqueIndex("app_user_roles_user_role_idx").on(table.userId, table.role) }));

export const authUsers = pgTable("auth_users", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  username: text("username"),
  displayUsername: text("display_username"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  emailUnique: uniqueIndex("auth_users_email_idx").on(table.email),
  usernameUnique: uniqueIndex("auth_users_username_idx").on(table.username),
}));

export const authSessions = pgTable("auth_sessions", {
  id: text("id").primaryKey(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  token: text("token").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  ipAddress: text("ip_address"),
  userAgent: text("user_agent"),
  userId: text("user_id").notNull().references(() => authUsers.id, { onDelete: "cascade" }),
}, (table) => ({
  tokenUnique: uniqueIndex("auth_sessions_token_idx").on(table.token),
  userIndex: index("auth_sessions_user_id_idx").on(table.userId),
}));

export const authAccounts = pgTable("auth_accounts", {
  id: text("id").primaryKey(),
  accountId: text("account_id").notNull(),
  providerId: text("provider_id").notNull(),
  userId: text("user_id").notNull().references(() => authUsers.id, { onDelete: "cascade" }),
  accessToken: text("access_token"),
  refreshToken: text("refresh_token"),
  idToken: text("id_token"),
  accessTokenExpiresAt: timestamp("access_token_expires_at", { withTimezone: true }),
  refreshTokenExpiresAt: timestamp("refresh_token_expires_at", { withTimezone: true }),
  scope: text("scope"),
  password: text("password"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  userIndex: index("auth_accounts_user_id_idx").on(table.userId),
}));

export const authVerifications = pgTable("auth_verifications", {
  id: text("id").primaryKey(),
  identifier: text("identifier").notNull(),
  value: text("value").notNull(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  identifierIndex: index("auth_verifications_identifier_idx").on(table.identifier),
}));

export const protectedAccountActorLinks = pgTable("protected_account_actor_links", {
  authUserId: text("auth_user_id").primaryKey().references(() => authUsers.id, { onDelete: "cascade" }),
  appUserId: text("app_user_id").notNull().references(() => appUsers.id, { onDelete: "cascade" }),
  whatsappPhoneE164: text("whatsapp_phone_e164"),
  whatsappPhoneConfirmedAt: timestamp("whatsapp_phone_confirmed_at", { withTimezone: true }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  oneAccountPerActor: uniqueIndex("protected_account_actor_links_app_user_idx").on(table.appUserId),
  whatsappPhoneStateValid: check("protected_account_whatsapp_phone_state_valid", sql`(
    (${table.whatsappPhoneE164} is null and ${table.whatsappPhoneConfirmedAt} is null)
    or
    (${table.whatsappPhoneE164} ~ '^\\+[1-9][0-9]{7,14}$' and ${table.whatsappPhoneConfirmedAt} is not null)
  )`),
}));

export const preferenceProfiles = pgTable("preference_profiles", {
  id: text("id").primaryKey(),
  userId: text("user_id").notNull().references(() => appUsers.id, { onDelete: "cascade" }),
  category: preferenceProfileCategory("category").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({ oneProfilePerUser: uniqueIndex("preference_profiles_user_id_idx").on(table.userId) }));

export const melodyEquivalenceClasses = pgTable("melody_equivalence_classes", {
  id: text("id").primaryKey(),
  label: text("label").notNull(),
  synthetic: boolean("synthetic").notNull().default(false),
});

export const songMelodyEquivalence = pgTable("song_melody_equivalence", {
  songId: text("song_id").notNull().references(() => catalogSongs.songId, { onDelete: "cascade" }),
  classId: text("class_id").notNull().references(() => melodyEquivalenceClasses.id, { onDelete: "cascade" }),
}, (table) => ({ oneClassPerSong: uniqueIndex("song_melody_equivalence_song_id_idx").on(table.songId) }));

export const songPreferences = pgTable("song_preferences", {
  profileId: text("profile_id").notNull().references(() => preferenceProfiles.id, { onDelete: "cascade" }),
  songId: text("song_id").notNull().references(() => catalogSongs.songId, { onDelete: "cascade" }),
  score: integer("score").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({ onePreferencePerProfileSong: uniqueIndex("song_preferences_profile_song_idx").on(table.profileId, table.songId), scoreRange: check("song_preferences_score_range", sql`${table.score} >= 0 and ${table.score} <= 3`) }));

export const referenceSongPreferences = pgTable("reference_song_preferences", {
  profileId: text("profile_id").notNull().references(() => preferenceProfiles.id, { onDelete: "cascade" }),
  referenceSongId: text("reference_song_id").notNull().references(() => referenceCatalogSongs.id, { onDelete: "cascade" }),
  score: integer("score").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({ onePreferencePerProfileReference: uniqueIndex("reference_song_preferences_profile_reference_song_idx").on(table.profileId, table.referenceSongId), scoreRange: check("reference_song_preferences_score_range", sql`${table.score} >= 0 and ${table.score} <= 3`) }));

export const referenceOrganistRepertoire = pgTable("reference_organist_repertoire", {
  organistPersonId: text("organist_person_id").notNull().references(() => catalogPersons.id, { onDelete: "cascade" }),
  referenceSongId: text("reference_song_id").notNull().references(() => referenceCatalogSongs.id, { onDelete: "cascade" }),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({ oneMembership: uniqueIndex("reference_organist_repertoire_person_song_idx").on(table.organistPersonId, table.referenceSongId) }));

export const referenceMelodyClasses = pgTable("reference_melody_classes", {
  id: text("id").primaryKey(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const referenceSongMelodyMemberships = pgTable("reference_song_melody_memberships", {
  referenceSongId: text("reference_song_id").primaryKey().references(() => referenceCatalogSongs.id, { onDelete: "cascade" }),
  classId: text("class_id").notNull().references(() => referenceMelodyClasses.id, { onDelete: "cascade" }),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({ classLookup: index("reference_song_melody_memberships_class_id_idx").on(table.classId) }));

export const referenceMelodyEdges = pgTable("reference_melody_edges", {
  songAId: text("song_a_id").notNull().references(() => referenceCatalogSongs.id, { onDelete: "cascade" }),
  songBId: text("song_b_id").notNull().references(() => referenceCatalogSongs.id, { onDelete: "cascade" }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  pair: uniqueIndex("reference_melody_edges_pair_idx").on(table.songAId, table.songBId),
  songBLookup: index("reference_melody_edges_song_b_idx").on(table.songBId),
  canonicalPair: check("reference_melody_edges_canonical_pair", sql`${table.songAId} < ${table.songBId}`),
}));

export const referenceAntiphonRecommendations = pgTable("reference_antiphon_recommendations", {
  antiphonId: text("antiphon_id").primaryKey().references(() => referenceAntiphons.id, { onDelete: "cascade" }),
  referenceSongId: text("reference_song_id").notNull().references(() => referenceCatalogSongs.id, { onDelete: "cascade" }),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({ songLookup: index("reference_antiphon_recommendations_song_id_idx").on(table.referenceSongId) }));

export const organistRepertoire = pgTable("organist_repertoire", {
  organistPersonId: text("organist_person_id").notNull().references(() => catalogPersons.id, { onDelete: "cascade" }),
  songId: text("song_id").notNull().references(() => catalogSongs.songId, { onDelete: "cascade" }),
}, (table) => ({ oneRepertoireMembership: uniqueIndex("organist_repertoire_person_song_idx").on(table.organistPersonId, table.songId) }));

export const antiphonMappings = pgTable("antiphon_mappings", { id: text("id").primaryKey(), antiphonKey: text("antiphon_key").notNull(), songId: text("song_id").notNull().references(() => catalogSongs.songId, { onDelete: "cascade" }), synthetic: boolean("synthetic").notNull().default(false) });
export const liturgicalSeasonMappings = pgTable("liturgical_season_mappings", { id: text("id").primaryKey(), seasonKey: text("season_key").notNull(), songId: text("song_id").notNull().references(() => catalogSongs.songId, { onDelete: "cascade" }), synthetic: boolean("synthetic").notNull().default(false) });
export const melodyNonRepetitionConfig = pgTable("melody_non_repetition_config", { id: text("id").primaryKey().default("global"), months: integer("months").notNull().default(2), updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow() }, (table) => ({ singletonConfig: check("melody_non_repetition_config_singleton", sql`${table.id} = 'global'`), nonNegativeWindow: check("melody_non_repetition_config_non_negative", sql`${table.months} >= 0`) }));

export const auditEvents = pgTable("audit_events", {
  id: serial("id").primaryKey(),
  occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull().defaultNow(),
  actorKind: text("actor_kind").notNull(),
  actorUserId: text("actor_user_id"),
  actorDisplayName: text("actor_display_name"),
  actorRole: text("actor_role"),
  actorPersonId: text("actor_person_id"),
  action: text("action").notNull(),
  objectKind: text("object_kind").notNull(),
  objectRef: text("object_ref").notNull(),
  beforeState: jsonb("before_state"),
  afterState: jsonb("after_state"),
}, (table) => ({
  occurredAtIndex: index("audit_events_occurred_at_idx").on(table.occurredAt),
  objectIndex: index("audit_events_object_idx").on(table.objectKind, table.objectRef),
  actorKindValid: check("audit_events_actor_kind_valid", sql`${table.actorKind} in ('human', 'system')`),
  actorSnapshotValid: check("audit_events_actor_snapshot_valid", sql`(
    ${table.actorKind} = 'system' and ${table.actorUserId} is null and ${table.actorDisplayName} is null and ${table.actorRole} is null
  ) or (
    ${table.actorKind} = 'human' and ${table.actorUserId} is not null and btrim(${table.actorUserId}) <> '' and
    ${table.actorDisplayName} is not null and btrim(${table.actorDisplayName}) <> '' and
    ${table.actorRole} is not null and btrim(${table.actorRole}) <> ''
  )`),
  actionNonEmpty: check("audit_events_action_non_empty", sql`btrim(${table.action}) <> ''`),
  objectKindNonEmpty: check("audit_events_object_kind_non_empty", sql`btrim(${table.objectKind}) <> ''`),
  objectRefNonEmpty: check("audit_events_object_ref_non_empty", sql`btrim(${table.objectRef}) <> ''`),
}));

export const serviceContextsRelations = relations(serviceContexts, ({ many }) => ({
  serviceSets: many(serviceSets),
  completedServices: many(completedServices),
}));

export const serviceSetsRelations = relations(serviceSets, ({ one, many }) => ({
  serviceContext: one(serviceContexts, {
    fields: [serviceSets.serviceContextId],
    references: [serviceContexts.id],
  }),
  rows: many(serviceSetRows),
  completedServices: many(completedServices),
}));

export const serviceSetRowsRelations = relations(serviceSetRows, ({ one }) => ({
  serviceSet: one(serviceSets, {
    fields: [serviceSetRows.serviceSetId],
    references: [serviceSets.id],
  }),
}));

export const completedServicesRelations = relations(completedServices, ({ one, many }) => ({
  serviceContext: one(serviceContexts, {
    fields: [completedServices.serviceContextId],
    references: [serviceContexts.id],
  }),
  serviceSet: one(serviceSets, {
    fields: [completedServices.serviceSetId],
    references: [serviceSets.id],
  }),
  rows: many(completedServiceRows),
}));

export const completedServiceRowsRelations = relations(completedServiceRows, ({ one }) => ({
  completedService: one(completedServices, {
    fields: [completedServiceRows.completedServiceId],
    references: [completedServices.id],
  }),
}));

import { randomUUID } from "node:crypto";
import type { Pool, PoolClient } from "pg";
import { appendAuditEvent, systemAuditActor } from "../application/audit-history";
import {
  AUDIT_RETENTION_FAILURE_ACTION,
  AUDIT_RETENTION_OBJECT_KIND,
  AUDIT_RETENTION_SUCCESS_ACTION,
  auditRetentionDryRun,
  type AuditRetentionDryRunReport,
} from "../application/audit-retention-maintenance";

export const AUDIT_RETENTION_LOCK_KEY = "organy.audit-retention";

export type AuditRetentionApplyReport = AuditRetentionDryRunReport & {
  mode: "apply";
  runRef: string;
  deletedPlanningAuditEvents: number;
  deletedResolvedFailureEvents: number;
};

export class AuditRetentionMaintenanceConflictError extends Error {
  constructor() {
    super("Another audit-retention maintenance run is already active.");
    this.name = "AuditRetentionMaintenanceConflictError";
  }
}

export async function applyAuditRetentionMaintenance(db: Pool): Promise<AuditRetentionApplyReport> {
  const runRef = `audit-retention:${new Date().toISOString()}:${randomUUID()}`;
  let client: PoolClient | undefined;

  try {
    client = await db.connect();
    await client.query("begin isolation level repeatable read");

    const lock = await client.query(
      "select pg_try_advisory_xact_lock(hashtextextended($1, 0)) as locked",
      [AUDIT_RETENTION_LOCK_KEY],
    );
    if (lock.rows[0]?.locked !== true) throw new AuditRetentionMaintenanceConflictError();

    const dryRun = await auditRetentionDryRun(client);
    let deletedPlanningAuditEvents = 0;
    let deletedResolvedFailureEvents = 0;

    if (dryRun.eligible && dryRun.cutoffServiceDate) {
      const planningDelete = await client.query(
        `delete from audit_events e
          where e.action like 'planning.%'
            and e.occurred_at < $1::date
            and not (
              e.object_kind = 'planningSet'
              and exists (
                select 1
                  from service_sets active_set
                 where active_set.id::text = e.object_ref
                   and active_set.status in ('working', 'final')
              )
            ) returning e.id`,
        [dryRun.cutoffServiceDate],
      );
      deletedPlanningAuditEvents = planningDelete.rows.length;

      const failureDelete = await client.query(
        `delete from audit_events failure
          where failure.action = $2
            and failure.occurred_at < $1::date
            and exists (
              select 1
                from audit_events success
               where success.action = $3
                 and (success.occurred_at, success.id) > (failure.occurred_at, failure.id)
            ) returning failure.id`,
        [dryRun.cutoffServiceDate, AUDIT_RETENTION_FAILURE_ACTION, AUDIT_RETENTION_SUCCESS_ACTION],
      );
      deletedResolvedFailureEvents = failureDelete.rows.length;
    }

    const report: AuditRetentionApplyReport = {
      ...dryRun,
      mode: "apply",
      runRef,
      deletedPlanningAuditEvents,
      deletedResolvedFailureEvents,
    };

    await appendAuditEvent(client, {
      actor: systemAuditActor(),
      action: AUDIT_RETENTION_SUCCESS_ACTION,
      objectKind: AUDIT_RETENTION_OBJECT_KIND,
      objectRef: runRef,
      afterState: {
        status: "success",
        ...report,
      },
    });

    await client.query("commit");
    return report;
  } catch (error) {
    if (client) {
      await client.query("rollback").catch(() => undefined);
      await appendFailureAudit(client, runRef, error).catch((auditError) => {
        console.error(
          "Audit retention failure event could not be persisted.",
          auditError instanceof Error ? auditError.message : "Unknown audit persistence error.",
        );
      });
    }
    throw error;
  } finally {
    client?.release();
  }
}

async function appendFailureAudit(client: PoolClient, runRef: string, error: unknown): Promise<void> {
  await appendAuditEvent(client, {
    actor: systemAuditActor(),
    action: AUDIT_RETENTION_FAILURE_ACTION,
    objectKind: AUDIT_RETENTION_OBJECT_KIND,
    objectRef: runRef,
    afterState: {
      status: "failure",
      mode: "apply",
      conflict: error instanceof AuditRetentionMaintenanceConflictError,
      errorName: error instanceof Error ? error.name : "UnknownError",
      errorMessage: error instanceof Error ? error.message : "Unknown maintenance error.",
    },
  });
}

export const PHASE_30_1_PREFERENCE_THRESHOLD = 0;

import type { CatalogSong } from "../application/catalog";
import type { CandidateQueryInput, CandidateQueryResult, CandidateUsage, RowLookupState } from "../application/interaction-contracts";
import type { ConcreteSongLanguage, ServiceLanguage } from "./model";

export type CandidatePopupAction = "select" | "cancel";

export type CandidatePopupRow = Pick<
  CandidateQueryResult,
  "songId" | "language" | "number" | "title" | "signal" | "preferenceShade" | "repertoire" | "aggregatePreferenceScore" | "availability"
> & {
  actions: CandidatePopupAction[];
};

export type SelectedSongCandidateLine = Pick<
  CandidateQueryResult,
  "songId" | "language" | "number" | "title" | "signal" | "preferenceShade" | "repertoire" | "aggregatePreferenceScore"
> & {
  kind: "candidate";
  detailAction: true;
};

export type SelectedSongNoteLine = {
  kind: "note";
  text: string;
};

export type SelectedSongPresentation = {
  lines: [SelectedSongCandidateLine, SelectedSongNoteLine];
};

export type PlanningLookupState =
  | { status: "idle"; detailNavigation?: DetailNavigation }
  | { status: "lookupActive"; text: string; detailNavigation?: DetailNavigation }
  | { status: "selected"; presentation: SelectedSongPresentation; detailNavigation?: DetailNavigation };

export type DetailNavigation = { songId: string; returnRowId: number };

export type PlanningLookupAction =
  | { type: "lookupChanged"; text: string }
  | { type: "candidateSelected"; candidate: CandidateQueryResult; note: string }
  | { type: "lookupCancelled" }
  | { type: "detailOpened"; songId: string; returnRowId: number }
  | { type: "detailReturned" };

export type PlanningCandidateEditableRow = {
  id: number;
  songSearch: string;
  selectedSong?: CatalogSong | { songId?: string; language: ConcreteSongLanguage; number: string; title?: string };
  selectedCandidate?: CandidateQueryResult;
  note: string;
  lookupOpen?: boolean;
};

export type PlanningCandidateRowAction =
  | { type: "lookupOpened" }
  | { type: "lookupChanged"; text: string }
  | { type: "candidateSelected"; song: CatalogSong | { songId?: string; language: ConcreteSongLanguage; number: string; title?: string }; candidate?: CandidateQueryResult }
  | { type: "lookupCancelled" }
  | { type: "rowDeactivated" }
  | { type: "songCleared" }
  | { type: "rowCleared" }
  | { type: "noteChanged"; note: string };

export type CandidateQueryContextInput = {
  serviceDate: string;
  serviceLanguage: ServiceLanguage;
  organistPersonId?: string;
  referenceAntiphonId?: string;
  referenceTopicId?: string;
  antiphonKey?: string;
  liturgicalSeasonKey?: string;
  candidateUsages?: CandidateUsage[];
  currentPlanId?: string;
  queryText?: string;
  preferenceThreshold?: number;
  historicalTruth?: boolean;
};

export function getCandidatePopupRows(candidates: CandidateQueryResult[]): CandidatePopupRow[] {
  return candidates.filter((candidate) => !candidate.suppressedByMelodyWindow).map((candidate) => ({
    songId: candidate.songId,
    language: candidate.language,
    number: candidate.number,
    title: candidate.title,
    signal: candidate.signal,
    preferenceShade: candidate.preferenceShade,
    repertoire: candidate.repertoire,
    aggregatePreferenceScore: candidate.aggregatePreferenceScore,
    availability: candidate.availability,
    actions: candidate.availability.kind === "available" ? ["select"] : [],
  }));
}

export function getSelectedSongPresentation(candidate: CandidateQueryResult, note: string): SelectedSongPresentation {
  return {
    lines: [
      {
        kind: "candidate",
        songId: candidate.songId,
        language: candidate.language,
        number: candidate.number,
        title: candidate.title,
        signal: candidate.signal,
        preferenceShade: candidate.preferenceShade,
        repertoire: candidate.repertoire,
        aggregatePreferenceScore: candidate.aggregatePreferenceScore,
        detailAction: true,
      },
      { kind: "note", text: note },
    ],
  };
}

export function planningLookupReducer(state: PlanningLookupState, action: PlanningLookupAction): PlanningLookupState {
  switch (action.type) {
    case "lookupChanged":
      return action.text.trim() ? { status: "lookupActive", text: action.text, detailNavigation: state.detailNavigation } : { status: "idle", detailNavigation: state.detailNavigation };
    case "candidateSelected":
      return { status: "selected", presentation: getSelectedSongPresentation(action.candidate, action.note), detailNavigation: state.detailNavigation };
    case "lookupCancelled":
      return { status: "idle", detailNavigation: state.detailNavigation };
    case "detailOpened":
      return { ...state, detailNavigation: { songId: action.songId, returnRowId: action.returnRowId } };
    case "detailReturned": {
      const { detailNavigation: _detailNavigation, ...rest } = state;
      return rest;
    }
  }
}

export function buildCandidateQueryInput(input: CandidateQueryContextInput): CandidateQueryInput {
  return {
    serviceDate: input.serviceDate,
    serviceLanguage: input.serviceLanguage,
    ...(input.organistPersonId ? { organistPersonId: input.organistPersonId } : {}),
    ...(input.referenceAntiphonId?.trim() ? { referenceAntiphonId: input.referenceAntiphonId.trim() } : {}),
    ...(input.referenceTopicId?.trim() ? { referenceTopicId: input.referenceTopicId.trim() } : {}),
    ...(input.antiphonKey?.trim() ? { antiphonKey: input.antiphonKey.trim() } : {}),
    ...(input.liturgicalSeasonKey?.trim() ? { liturgicalSeasonKey: input.liturgicalSeasonKey.trim() } : {}),
    ...(input.queryText?.trim() ? { queryText: input.queryText.trim() } : {}),
    preferenceThreshold: typeof input.preferenceThreshold === "number" ? input.preferenceThreshold : PHASE_30_1_PREFERENCE_THRESHOLD,
    ...(input.currentPlanId ? { currentPlanId: input.currentPlanId } : {}),
    candidateUsages: input.candidateUsages ?? [],
    ...(input.historicalTruth ? { historicalTruth: true } : {}),
  };
}

export function planningCandidateRowReducer(row: PlanningCandidateEditableRow, action: PlanningCandidateRowAction): PlanningCandidateEditableRow {
  switch (action.type) {
    case "lookupOpened":
      return { ...row, songSearch: row.selectedSong ? formatPlanningSongField(row.selectedSong) : "", lookupOpen: true };
    case "lookupChanged":
      return action.text.trim()
        ? { ...row, songSearch: action.text, lookupOpen: true }
        : { ...row, songSearch: "", selectedSong: undefined, selectedCandidate: undefined, lookupOpen: true };
    case "candidateSelected":
      return { ...row, songSearch: formatPlanningSongField(action.song), selectedSong: action.song, selectedCandidate: action.candidate, lookupOpen: false };
    case "lookupCancelled":
    case "rowDeactivated":
      return restoreConfirmedCandidate(row);
    case "songCleared":
      return { ...row, songSearch: "", selectedSong: undefined, selectedCandidate: undefined, lookupOpen: false };
    case "rowCleared":
      return { ...row, songSearch: "", selectedSong: undefined, selectedCandidate: undefined, note: "", lookupOpen: false };
    case "noteChanged":
      return { ...row, note: action.note };
  }
}

export function restoreConfirmedCandidate<T extends PlanningCandidateEditableRow>(row: T): T {
  return { ...row, lookupOpen: false, songSearch: row.selectedSong ? formatPlanningSongField(row.selectedSong) : "" };
}

export function restoreRowsExceptActive<T extends PlanningCandidateEditableRow>(rows: T[], targetRowId: number): T[] {
  return rows.map((row) => row.id === targetRowId ? row : row.lookupOpen ? restoreConfirmedCandidate(row) : row);
}

export function openSingleCandidateRow<T extends PlanningCandidateEditableRow>(rows: T[], targetRowId: number): T[] {
  return rows.map((row) => row.id === targetRowId
    ? planningCandidateRowReducer(row, { type: "lookupOpened" }) as T
    : row.lookupOpen ? restoreConfirmedCandidate(row) : row);
}

export function getPlanningCandidateRowLookupState(row: PlanningCandidateEditableRow): RowLookupState {
  const confirmedLabel = row.selectedSong ? formatPlanningSongField(row.selectedSong) : "";
  const hasUnconfirmedLookupText = Boolean(row.lookupOpen && row.songSearch.trim() && row.songSearch !== confirmedLabel);
  if (hasUnconfirmedLookupText) {
    const previous: Exclude<RowLookupState, { kind: "lookup" }> = row.selectedSong?.songId
      ? { kind: "selected", songId: row.selectedSong.songId }
      : row.note.trim()
        ? { kind: "noteOnly", note: row.note }
        : { kind: "empty" };
    return { kind: "lookup", text: row.songSearch, previous };
  }
  if (row.selectedSong?.songId) return { kind: "selected", songId: row.selectedSong.songId };
  if (row.note.trim()) return { kind: "noteOnly", note: row.note };
  return { kind: "empty" };
}

export function formatPlanningSongField(song: { number: string; title?: string }): string {
  return `${song.number}${song.title ? ` · ${song.title}` : ""}`;
}

export function formatSongLabel(song: { language: ConcreteSongLanguage; number: string; title?: string }): string {
  return `${song.language} ${song.number}${song.title ? ` — ${song.title}` : ""}`;
}

export function rehydrateCandidateFromSelectedSong(song: { songId?: string; language: ConcreteSongLanguage; number: string; title?: string }, _note = ""): CandidateQueryResult {
  const songId = song.songId ?? `historical:${song.language}:${song.number}`;
  return {
    songId,
    language: song.language,
    number: song.number,
    title: song.title ?? "Untitled snapshot",
    equivalentNumbers: [],
    aggregatePreferenceScore: 0,
    antiphonMatch: false,
    seasonMatch: false,
    signal: "none",
    preferenceShade: "none",
    repertoire: false,
    availability: { kind: "available" },
    suppressedByMelodyWindow: false,
    orderKey: `rehydrated:${song.language}:${song.number}:${songId}`,
  };
}

export function candidateToSelectedSong(candidate: CandidateQueryResult): { songId: string; language: ConcreteSongLanguage; number: string; title: string } {
  return { songId: candidate.songId, language: candidate.language, number: candidate.number, title: candidate.title };
}

export type CanonicalUsageInput = {
  currentPlanId?: string;
  serviceDate: string;
  completedRecords?: { id: string; serviceDate: string; rows: { songId?: string }[] }[];
  plans?: { id: string; status: "working" | "final"; serviceDate: string; rows: { songId?: string }[] }[];
  currentRows?: { rowId: number; rowLabel: string; songId?: string }[];
  activeRowId?: number;
};

export function buildCanonicalCandidateUsages(input: CanonicalUsageInput): CandidateUsage[] {
  const usages: CandidateUsage[] = [];
  for (const record of input.completedRecords ?? []) {
    for (const row of record.rows) if (row.songId) usages.push({ songId: row.songId, serviceDate: record.serviceDate, source: "completed", planId: record.id });
  }
  for (const plan of input.plans ?? []) {
    if (plan.id === input.currentPlanId) continue;
    for (const row of plan.rows) if (row.songId) usages.push({ songId: row.songId, serviceDate: plan.serviceDate, source: plan.status, planId: plan.id });
  }
  for (const row of input.currentRows ?? []) {
    if (row.rowId === input.activeRowId) continue;
    if (row.songId) usages.push({ songId: row.songId, serviceDate: input.serviceDate, source: "current", rowId: row.rowId, rowLabel: row.rowLabel });
  }
  return usages;
}

import type { ChangeEvent } from "react";
import type { CandidateQueryResult } from "../application/interaction-contracts";
import { getSelectedSongPresentation } from "./candidate-flow";

type CandidateLineProps =
  | { candidate: CandidateQueryResult; variant: "popup"; onSelect: () => void }
  | { candidate: CandidateQueryResult; variant: "selected"; note: string; readOnly?: boolean; detailButtonId?: string; onOpenDetail: () => void; onNoteChange?: (note: string) => void };

type CandidateNumberOption = {
  songId: string;
  number: string;
  language?: CandidateQueryResult["language"];
  repertoire: boolean;
  primary: boolean;
};

export type CandidateLineViewModel = {
  candidate: CandidateQueryResult;
  numberOptions: CandidateNumberOption[];
  tone: "positive" | "neutral" | "negative";
  backgroundClass: string;
  contentTextClass: string;
  accessibleMeaning: string;
  availabilityReason?: string;
};

export function getCandidateLineViewModel(candidate: CandidateQueryResult): CandidateLineViewModel {
  const numberOptions: CandidateNumberOption[] = [
    { songId: candidate.songId, number: candidate.number, language: candidate.language, repertoire: candidate.repertoire, primary: true },
    ...candidate.equivalentNumbers.map((item) => ({ ...item, language: referenceLanguageFromSongId(item.songId), primary: false })),
  ].sort((a, b) => `${a.primary ? 0 : a.repertoire ? 1 : 2}:${a.number}`.localeCompare(`${b.primary ? 0 : b.repertoire ? 1 : 2}:${b.number}`));
  const tone: CandidateLineViewModel["tone"] = candidate.suppressedByMelodyWindow || candidate.antiphonMatch ? "negative" : candidate.seasonMatch ? "positive" : "neutral";
  const backgroundClass = `candidate-tone-${tone} candidate-preference-${candidate.preferenceShade}`;
  const contentTextClass = `candidate-content-text candidate-text-${tone}`;
  const optionMeaning = numberOptions.map((item) => `${item.primary ? "primary" : "equivalent"} ${item.number}${item.language ? ` ${item.language}` : ""}; ${item.repertoire ? "in organist repertoire" : "not in organist repertoire"}`).join("; ");
  const availabilityReason = candidate.availability.kind === "occupiedByCurrentRows"
    ? `Same melody is already used in ${joinLabels(candidate.availability.rows.map((row) => row.label))}.`
    : undefined;
  const accessibleMeaning = `${tone === "positive" ? "green positive" : tone === "negative" ? "red negative" : "neutral"} candidate; ${optionMeaning}${availabilityReason ? `; unavailable: ${availabilityReason}` : ""}`;
  return { candidate, numberOptions, tone, backgroundClass, contentTextClass, accessibleMeaning, availabilityReason };
}

export function CandidateLine(props: CandidateLineProps) {
  const viewModel = getCandidateLineViewModel(props.candidate);
  if (props.variant === "popup") {
    return (
      <div className={`candidate-card candidate-card-compact ${viewModel.backgroundClass}`} data-candidate-line="popup" aria-label={viewModel.accessibleMeaning}>
        <button type="button" disabled={Boolean(viewModel.availabilityReason)} aria-disabled={Boolean(viewModel.availabilityReason)} onClick={() => { if (!viewModel.availabilityReason) props.onSelect(); }}><span className={viewModel.contentTextClass}><CandidateSummary viewModel={viewModel} /><span>{props.candidate.title} · {props.candidate.language} · {props.candidate.signal}</span></span></button>
        {viewModel.availabilityReason && <span className="field-help" role="status">{viewModel.availabilityReason}</span>}
      </div>
    );
  }

  const presentation = getSelectedSongPresentation(props.candidate, props.note);
  const candidateLine = presentation.lines[0];
  const noteLine = presentation.lines[1];
  return (
    <div className={`selected-song-card ${viewModel.backgroundClass}`} data-candidate-line="selected" aria-label={viewModel.accessibleMeaning}>
      <div className="selected-song-summary" data-content-row="candidate">
        <span className={viewModel.contentTextClass}><CandidateSummary viewModel={viewModel} />
        <span>{candidateLine.title || "Untitled snapshot"} · {candidateLine.language} · {candidateLine.signal}</span></span>
        <button id={props.detailButtonId} type="button" className="candidate-detail-button" onClick={props.onOpenDetail}>Detail</button>
      </div>
      <div className="selected-song-note-row" data-content-row="note">
        {props.readOnly ? <span>{noteLine.text.trim() ? noteLine.text : "No text note."}</span> : <input aria-label="Text note" type="text" value={noteLine.text} onChange={(event: ChangeEvent<HTMLInputElement>) => props.onNoteChange?.(event.target.value)} placeholder="Optional note without a song" />}
      </div>
    </div>
  );
}

function CandidateSummary({ viewModel }: { viewModel: CandidateLineViewModel }) {
  return (
    <span className="candidate-number-options">
      {viewModel.numberOptions.map((item) => (
        <span key={item.songId} className={item.primary ? "candidate-number-primary" : "candidate-number-equivalent"}>
          {!item.primary && <span>equivalent </span>}
          {item.primary ? <strong className="sticky-song-number">{item.number}</strong> : item.repertoire ? <strong>{item.number}</strong> : <span>{item.number}</span>}
          <span> · {item.language ? `${item.language} · ` : ""}{item.repertoire ? "in repertoire" : "not in repertoire"}</span>
        </span>
      ))}
    </span>
  );
}

function referenceLanguageFromSongId(songId: string): CandidateQueryResult["language"] | undefined {
  if (songId.startsWith("czech:")) return "czech";
  if (songId.startsWith("polish:")) return "polish";
  return undefined;
}

function joinLabels(labels: string[]): string {
  if (labels.length <= 1) return labels[0] ?? "another row";
  if (labels.length === 2) return `${labels[0]} and ${labels[1]}`;
  return `${labels.slice(0, -1).join(", ")}, and ${labels.at(-1)}`;
}

